(()=>{
const dialog=document.querySelector('#admin-password-dialog'),form=document.querySelector('#admin-password-form'),feedback=document.querySelector('#admin-password-feedback'),toggle=document.querySelector('#show-admin-passwords'),login=document.querySelector('#admin-password-login'),submit=form.querySelector('[type=submit]');let busy=false;
function reset(){form.reset();form.hidden=false;login.hidden=true;feedback.textContent='';submit.disabled=false;form.querySelectorAll('input').forEach(f=>f.type='password');toggle.textContent='إظهار كلمات المرور';toggle.setAttribute('aria-pressed','false')}
document.querySelector('#open-admin-password').onclick=()=>{reset();dialog.showModal();form.elements.current_password.focus()};
document.querySelector('#close-admin-password').onclick=()=>{if(!busy){dialog.close();reset()}};
dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault()});dialog.addEventListener('close',()=>{if(!busy)reset()});
toggle.onclick=()=>{const visible=toggle.getAttribute('aria-pressed')!=='true';form.querySelectorAll('input').forEach(f=>f.type=visible?'text':'password');toggle.setAttribute('aria-pressed',String(visible));toggle.textContent=visible?'إخفاء كلمات المرور':'إظهار كلمات المرور'};
form.addEventListener('keydown',event=>{if(event.key!=='Enter'||!event.target.matches('input'))return;event.preventDefault();const fields=[...form.querySelectorAll('input')],next=fields[fields.indexOf(event.target)+1];if(event.target.reportValidity()){if(next)next.focus();else submit.focus()}});
form.onsubmit=async event=>{event.preventDefault();if(busy)return;feedback.textContent='';const data=Object.fromEntries(new FormData(form));for(const field of form.querySelectorAll('input')){if(!/^[!-~]{6,128}$/.test(field.value)){feedback.textContent='استخدم 6 إلى 128 محرفًا إنجليزيًا أو رقمًا أو رمزًا دون مسافات أو أحرف عربية.';field.focus();return}}if(data.password!==data.password_confirmation){feedback.textContent='كلمتا المرور الجديدتان غير متطابقتين.';form.elements.password_confirmation.focus();return}busy=true;submit.disabled=true;submit.textContent='جارٍ الحفظ…';try{await window.OwaysAPI.request('/api/admin/password',data);form.reset();form.hidden=true;feedback.textContent='تم تغيير كلمة المرور وإنهاء جميع الجلسات. سجّل الدخول بالكلمة الجديدة.';login.hidden=false;login.focus()}catch(error){feedback.textContent=error.message;form.elements.current_password.value='';form.elements.current_password.focus()}finally{busy=false;submit.disabled=false;submit.textContent='حفظ كلمة المرور'}};
})();